     VALUES ($1, $2, $3, 'viewer')`,
    [`membership:${suffix}:browser-viewer`, fixture.workspaceId, invitedFixture.userId],
  );

  const appRoot = resolve(projectRoot, "app");
  const originalWorkingDirectory = process.cwd();
