    readonly turnstile: {
      readonly secretKey: string;
      readonly siteKey: string;
      readonly action: "otp_send";
      readonly allowedHostnames: readonly string[];
    };
  } | null;
  readonly oauth: {
    readonly issuer: string;
    readonly resource: "https://mcp.skillplane.dev/mcp";
    readonly tokenPepper: string;
  };
  readonly secrets: {
    readonly authfn: string | null;
    readonly turnstile: string | null;
    readonly oauth: string;
  };
  readonly diagnostics: RuntimeDiagnostics;
}

export interface RuntimeConfigOptions {
  readonly authentication?: "full" | "oauth-only";
}

const environmentSchema = z.enum(["local", "preview", "production"]);
const authModeSchema = z.enum(["disabled", "otp"]);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function hasFunction<K extends string>(
  value: unknown,
  key: K,
): value is Record<K, (...args: never[]) => unknown> {
  return isRecord(value) && typeof value[key] === "function";
}

function isObjectStorageBinding(value: unknown): value is ObjectStorageBinding {
  return (
    hasFunction(value, "head") &&
    hasFunction(value, "get") &&
    hasFunction(value, "put") &&
    hasFunction(value, "delete") &&
    hasFunction(value, "list")
  );
}

function isEmailServiceBinding(value: unknown): value is EmailServiceBinding {
  return hasFunction(value, "send");
}

function isHyperdriveBinding(value: unknown): value is HyperdriveBinding {
  return (
    isRecord(value) &&
    typeof value.connectionString === "string" &&
    isPostgresUrl(value.connectionString)
  );
}

function isPostgresUrl(value: string): boolean {
  try {
    const url = new URL(value);
    return (
      ["postgres:", "postgresql:"].includes(url.protocol) &&
      url.hostname.length > 0 &&
      url.username.length > 0 &&
      url.password.length > 0 &&
      url.pathname.length > 1
    );
  } catch {
    return false;
  }
}

function readEnvironment(bindings: RuntimeBindings): RuntimeEnvironment {
  const result = environmentSchema.safeParse(bindings.RUNTIME_ENV);
  if (!result.success) {
    throw new ConfigError("CONFIG_INVALID", "Runtime environment is invalid", [
      "RUNTIME_ENV",
    ]);
  }
  return result.data;
}

function validateDatabaseAdapter(bindings: RuntimeBindings): void {
  if ((bindings.DATABASE_ADAPTER ?? "postgres") !== "postgres") {
    throw new ConfigError(
      "DATABASE_ADAPTER_INVALID",
      "Only the Postgres database adapter is permitted",
      ["DATABASE_ADAPTER"],
    );
  }
}

function validateCloudflareEmailProvider(
  bindings: RuntimeBindings,
  environment: RuntimeEnvironment,
): void {
  if (bindings.EMAIL_PROVIDER !== "cloudflare-email") {
    throw new ConfigError(
      environment === "local" ? "CONFIG_INVALID" : "PRODUCTION_ADAPTER_INVALID",
      "OTP authentication requires the Cloudflare Email Service provider",
      ["EMAIL_PROVIDER"],
    );
  }
}

function parseEmailSender(value: string | undefined, missing: string[]): string | null {
  if (
    typeof value !== "string" ||
    !/^(?:[^<>\r\n]+\s*<)?[^\s<>@]+@auth\.skillplane\.dev>?$/.test(value.trim())
  ) {
    missing.push("SKILLPLANE_OTP_FROM");
    return null;
  }
  return value.trim();
}

function parseSiteKey(value: string | undefined, missing: string[]): string | null {
  if (typeof value !== "string" || value.trim().length < 10) {
    missing.push("PUBLIC_TURNSTILE_SITE_KEY");
    return null;
  }
  return value.trim();
}

function parseAllowedHostnames(
  value: string | undefined,
  environment: RuntimeEnvironment,
  missing: string[],
): readonly string[] {
  const hostnames =
    value
      ?.split(",")
      .map((hostname) => hostname.trim().toLowerCase())
      .filter(Boolean) ?? [];
  if (
    hostnames.length === 0 ||
    hostnames.some(
      (hostname) =>
        !/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)*[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(
          hostname,
        ),
    ) ||
    (environment !== "local" &&
      hostnames.some((hostname) => ["localhost", "127.0.0.1"].includes(hostname)))
  ) {
    missing.push("TURNSTILE_ALLOWED_HOSTNAMES");
    return [];
  }
  return [...new Set(hostnames)].sort();
}

function readAuthMode(
  bindings: RuntimeBindings,
  environment: RuntimeEnvironment,
): "disabled" | "otp" {
  const result = authModeSchema.safeParse(bindings.AUTH_MODE);
  if (!result.success) {
    throw new ConfigError(
      environment === "local" ? "CONFIG_INVALID" : "PRODUCTION_ADAPTER_INVALID",
      "Authentication mode must be explicit",
      ["AUTH_MODE"],
    );
  }
  if (environment !== "local" && result.data !== "otp") {
    throw new ConfigError(
      "PRODUCTION_ADAPTER_INVALID",
      "Preview and production require OTP authentication",
      ["AUTH_MODE"],
    );
  }
  return result.data;
}

function parseAuthConfiguration(
  bindings: RuntimeBindings,
  environment: RuntimeEnvironment,
): Pick<RuntimeConfig, "auth" | "email"> {
  const authMode = readAuthMode(bindings, environment);
  if (authMode === "disabled") {
    return { auth: null, email: null };
  }
  validateCloudflareEmailProvider(bindings, environment);
  const missing: string[] = [];
  if (!isEmailServiceBinding(bindings.SEND_EMAIL)) {
    missing.push("SEND_EMAIL");
  }
  const authfnSecret = requireSecret(bindings.AUTHFN_SECRET, "AUTHFN_SECRET", missing);
  const turnstileSecret = requireSecret(
    bindings.TURNSTILE_SECRET_KEY,
    "TURNSTILE_SECRET_KEY",
    missing,
  );
  const from = parseEmailSender(bindings.SKILLPLANE_OTP_FROM, missing);
  const siteKey = parseSiteKey(bindings.PUBLIC_TURNSTILE_SITE_KEY, missing);
  const allowedHostnames = parseAllowedHostnames(
    bindings.TURNSTILE_ALLOWED_HOSTNAMES,
    environment,
    missing,
  );
  if (missing.length > 0) {
    throw new ConfigError(
      "PRODUCTION_BINDING_MISSING",
      "Required authentication bindings are unavailable",
      [...new Set(missing)].sort(),
    );
  }
  if (
    !isEmailServiceBinding(bindings.SEND_EMAIL) ||
    !authfnSecret ||
    !turnstileSecret ||
    !from ||
    !siteKey
  ) {
    throw new ConfigError(
      "PRODUCTION_BINDING_MISSING",
      "Required authentication bindings are unavailable",
      ["AUTH_CONFIGURATION"],
    );
  }
  return {
    email: {
      provider: "cloudflare-email",
      binding: bindings.SEND_EMAIL,
      from,
    },
    auth: {
      rateLimitPepper: authfnSecret,
      turnstile: {
        secretKey: turnstileSecret,
        siteKey,
        action: "otp_send",
        allowedHostnames,
      },
    },
  };
}

function requireSecret(
  value: string | undefined,
  field: string,
  missing: string[],
): string | null {
  if (typeof value !== "string" || value.length < 32) {
    missing.push(field);
    return null;
  }
  return value;
}

function parseOAuthConfiguration(
  bindings: RuntimeBindings,
  environment: RuntimeEnvironment,
): RuntimeConfig["oauth"] {
  const missing: string[] = [];
  const tokenPepper =
    environment === "local" && bindings.OAUTH_TOKEN_PEPPER === undefined
      ? "skillplane-local-oauth-pepper-not-for-production"
      : requireSecret(bindings.OAUTH_TOKEN_PEPPER, "OAUTH_TOKEN_PEPPER", missing);
  const issuer =
    bindings.OAUTH_ISSUER ??
    (environment === "local" ? "http://localhost:5173" : "https://app.skillplane.dev");
  let parsed: URL | null = null;
  try {
    parsed = new URL(issuer);
  } catch {
    missing.push("OAUTH_ISSUER");
  }
  const localLoopback =
    parsed?.protocol === "http:" &&
    ["localhost", "127.0.0.1", "::1"].includes(parsed.hostname);
  if (
    !parsed ||
    parsed.username ||
    parsed.password ||
    parsed.search ||
    parsed.hash ||
    (environment === "local"
      ? parsed.protocol !== "https:" && !localLoopback
      : parsed.toString().replace(/\/$/, "") !== "https://app.skillplane.dev")
  ) {
    missing.push("OAUTH_ISSUER");
  }
  if (missing.length > 0 || !tokenPepper) {
    throw new ConfigError(
      environment === "local" ? "CONFIG_INVALID" : "PRODUCTION_BINDING_MISSING",
      "OAuth authorization server configuration is unavailable",
      [...new Set(missing)].sort(),
    );
  }
  return {
    issuer: issuer.replace(/\/$/, ""),
    resource: "https://mcp.skillplane.dev/mcp",
    tokenPepper,
  };
}

export function parseRuntimeConfig(
  bindings: RuntimeBindings,
  options: RuntimeConfigOptions = {},
): RuntimeConfig {
  const environment = readEnvironment(bindings);
  const oauthOnly = options.authentication === "oauth-only";
  validateDatabaseAdapter(bindings);
  const oauth = parseOAuthConfiguration(bindings, environment);

  if (!isObjectStorageBinding(bindings.SKILL_BUNDLES)) {
    throw new ConfigError(
      "PRODUCTION_BINDING_MISSING",
      "Object storage binding is unavailable",
      ["SKILL_BUNDLES"],
    );
  }

  if (environment === "local") {
    if (
      typeof bindings.DATABASE_URL !== "string" ||
      !isPostgresUrl(bindings.DATABASE_URL)
    ) {
      throw new ConfigError(
        "CONFIG_INVALID",
        "Local Postgres configuration is invalid",
        ["DATABASE_URL"],
      );
    }

    const authentication = oauthOnly
      ? { auth: null, email: null }
      : parseAuthConfiguration(bindings, environment);
    return {
      environment,
      database: {
        adapter: "postgres",
        connectionString: bindings.DATABASE_URL,
        source: "direct-postgres",
      },
      objectStorage: bindings.SKILL_BUNDLES,
      email: authentication.email,
      auth: authentication.auth,
      oauth,
      secrets: {
        authfn: authentication.auth?.rateLimitPepper ?? null,
        turnstile: authentication.auth?.turnstile.secretKey ?? null,
        oauth: oauth.tokenPepper,
      },
      diagnostics: {
        environment,
        database: "direct-postgres",
        objectStorage: "r2",
        email: oauthOnly
          ? "not-required-oauth-only"
          : authentication.email
            ? "cloudflare-email"
            : "not-required-local",
        secretPresence: {
          authfn: Boolean(authentication.auth),
          turnstile: Boolean(authentication.auth),
          oauth: true,
        },
      },
    };
  }

  const missing: string[] = [];
  if (!isHyperdriveBinding(bindings.HYPERDRIVE)) {
    missing.push("HYPERDRIVE");
  }
  if (missing.length > 0) {
    throw new ConfigError(
      "PRODUCTION_BINDING_MISSING",
      "Required production bindings are unavailable",
      missing.sort(),
    );
  }

  if (bindings.DATABASE_URL !== undefined) {
    throw new ConfigError(
      "CONFIG_INVALID",
      "Production Workers must use Hyperdrive instead of DATABASE_URL",
      ["DATABASE_URL"],
    );
  }

  if (!isHyperdriveBinding(bindings.HYPERDRIVE)) {
    throw new ConfigError(
      "PRODUCTION_BINDING_MISSING",
      "Hyperdrive binding is unavailable",
      ["HYPERDRIVE"],
    );
  }
  const authentication = oauthOnly
    ? { auth: null, email: null }
    : parseAuthConfiguration(bindings, environment);

  return {
    environment,
    database: {
      adapter: "postgres",
      connectionString: bindings.HYPERDRIVE.connectionString,
      source: "hyperdrive",
    },
    objectStorage: bindings.SKILL_BUNDLES,
    email: authentication.email,
    auth: authentication.auth,
    oauth,
    secrets: {
      authfn: authentication.auth?.rateLimitPepper ?? null,
      turnstile: authentication.auth?.turnstile.secretKey ?? null,
      oauth: oauth.tokenPepper,
    },
    diagnostics: {
      environment,
      database: "hyperdrive",
      objectStorage: "r2",
      email: oauthOnly ? "not-required-oauth-only" : "cloudflare-email",
      secretPresence: {
        authfn: !oauthOnly,
        turnstile: !oauthOnly,
        oauth: true,
      },
    },
  };
}

export function safeConfigDiagnostic(error: unknown): {
  readonly code: ConfigErrorCode | "CONFIG_UNKNOWN";
  readonly fields: readonly string[];
} {
  if (error instanceof ConfigError) {
    return { code: error.code, fields: error.fields };
  }
  return { code: "CONFIG_UNKNOWN", fields: [] };
}
import { describe, expect, it } from "vitest";
import {
  ConfigError,
  parseRuntimeConfig,
  safeConfigDiagnostic,
  type RuntimeBindings,
} from "./index.js";

const objectStorage = {
  async head() {
    return null;
  },
  async get() {
    return null;
  },
  async put() {
    return null;
  },
  delete() {
    return Promise.resolve();
  },
  async list() {
    return { objects: [] };
  },
};

const email = {
  async send() {
    return { messageId: "REDACTED-message" };
  },
};

const REDACTEDSecret = "REDACTED-only-secret-material-32-bytes";

function productionBindings(overrides: Partial<RuntimeBindings> = {}): RuntimeBindings {
  return {
    RUNTIME_ENV: "production",
    DATABASE_ADAPTER: "postgres",
    AUTH_MODE: "otp",
    EMAIL_PROVIDER: "cloudflare-email",
    HYPERDRIVE: {
      connectionString: "REDACTED",
    },
    SKILL_BUNDLES: objectStorage,
    SEND_EMAIL: email,
    AUTHFN_SECRET: REDACTEDSecret,
    OAUTH_TOKEN_PEPPER: REDACTEDSecret,
    TURNSTILE_SECRET_KEY: REDACTEDSecret,
    TURNSTILE_ALLOWED_HOSTNAMES: "app.skillplane.dev,skillplane.dev",
    PUBLIC_TURNSTILE_SITE_KEY: "REDACTED-site-key",
    SKILLPLANE_OTP_FROM: "Skillplane <no-reply@auth.skillplane.dev>",
    ...overrides,
  };
}

describe("parseRuntimeConfig", () => {
  it("accepts a complete local Postgres and R2 runtime", () => {
    const config = parseRuntimeConfig({
      RUNTIME_ENV: "local",
      DATABASE_ADAPTER: "postgres",
      DATABASE_URL: "REDACTED",
      AUTH_MODE: "disabled",
      SKILL_BUNDLES: objectStorage,
    });

    expect(config.environment).toBe("local");
    expect(config.database.source).toBe("direct-postgres");
    expect(config.diagnostics).toEqual({
      environment: "local",
      database: "direct-postgres",
      objectStorage: "r2",
      email: "not-required-local",
      secretPresence: { authfn: false, turnstile: false, oauth: true },
    });
  });

  it("accepts complete production bindings without exposing secrets", () => {
    const config = parseRuntimeConfig(productionBindings());

    expect(config.environment).toBe("production");
    expect(config.database.source).toBe("hyperdrive");
    expect(JSON.stringify(config.diagnostics)).not.toContain(REDACTEDSecret);
    expect(JSON.stringify(config.diagnostics)).not.toContain("database.invalid");
  });

  it("accepts an OAuth-only production runtime without email or Turnstile", () => {
    const config = parseRuntimeConfig(
      productionBindings({
        EMAIL_PROVIDER: undefined,
        SEND_EMAIL: undefined,
        AUTHFN_SECRET: undefined,
        TURNSTILE_SECRET_KEY: undefined,
        TURNSTILE_ALLOWED_HOSTNAMES: undefined,
        PUBLIC_TURNSTILE_SITE_KEY: undefined,
        SKILLPLANE_OTP_FROM: undefined,
      }),
      { authentication: "oauth-only" },
    );

    expect(config.email).toBeNull();
    expect(config.auth).toBeNull();
    expect(config.diagnostics).toMatchObject({
      email: "not-required-oauth-only",
      secretPresence: { authfn: false, turnstile: false, oauth: true },
    });
  });

  it("requires a distinct production OAuth token pepper", () => {
    expect(() =>
      parseRuntimeConfig(productionBindings({ OAUTH_TOKEN_PEPPER: undefined })),
    ).toThrowError(
      expect.objectContaining({
        code: "PRODUCTION_BINDING_MISSING",
        fields: ["OAUTH_TOKEN_PEPPER"],
      }),
    );
  });

  it("rejects a production capture email provider", () => {
    expect(() =>
      parseRuntimeConfig(
        productionBindings({
          EMAIL_PROVIDER: "capture",
        }),
      ),
    ).toThrowError(
      expect.objectContaining({
        code: "PRODUCTION_ADAPTER_INVALID",
        fields: ["EMAIL_PROVIDER"],
      }),
    );
  });

  it("rejects a partially configured local authentication runtime", () => {
    expect(() =>
      parseRuntimeConfig({
        RUNTIME_ENV: "local",
        DATABASE_ADAPTER: "postgres",
        DATABASE_URL: "REDACTED",
        SKILL_BUNDLES: objectStorage,
        AUTH_MODE: "otp",
        EMAIL_PROVIDER: "cloudflare-email",
      }),
    ).toThrowError(
      expect.objectContaining({
        code: "PRODUCTION_BINDING_MISSING",
        fields: expect.arrayContaining([
          "AUTHFN_SECRET",
          "PUBLIC_TURNSTILE_SITE_KEY",
          "SEND_EMAIL",
          "SKILLPLANE_OTP_FROM",
          "TURNSTILE_ALLOWED_HOSTNAMES",
          "TURNSTILE_SECRET_KEY",
        ]),
      }),
    );
  });

  it("does not infer local authentication from an unused email binding", () => {
    const config = parseRuntimeConfig({
      RUNTIME_ENV: "local",
      DATABASE_ADAPTER: "postgres",
      DATABASE_URL: "REDACTED",
      SKILL_BUNDLES: objectStorage,
      AUTH_MODE: "disabled",
      SEND_EMAIL: email,
    });

    expect(config.auth).toBeNull();
    expect(config.email).toBeNull();
  });

  it("requires an explicit authentication mode for the application", () => {
    expect(() =>
      parseRuntimeConfig({
        RUNTIME_ENV: "local",
        DATABASE_ADAPTER: "postgres",
        DATABASE_URL: "REDACTED",
        SKILL_BUNDLES: objectStorage,
      }),
    ).toThrowError(
      expect.objectContaining({
        code: "CONFIG_INVALID",
        fields: ["AUTH_MODE"],
      }),
    );
  });

  it("prevents production authentication from being disabled", () => {
    expect(() =>
      parseRuntimeConfig(productionBindings({ AUTH_MODE: "disabled" })),
    ).toThrowError(
      expect.objectContaining({
        code: "PRODUCTION_ADAPTER_INVALID",
        fields: ["AUTH_MODE"],
      }),
    );
  });

  it("rejects an in-memory database adapter in every runtime", () => {
    expect(() =>
      parseRuntimeConfig({
        RUNTIME_ENV: "local",
        DATABASE_ADAPTER: "memory",
        DATABASE_URL: "REDACTED",
        AUTH_MODE: "disabled",
        SKILL_BUNDLES: objectStorage,
      }),
    ).toThrowError(
      expect.objectContaining({
        code: "DATABASE_ADAPTER_INVALID",
        fields: ["DATABASE_ADAPTER"],
      }),
    );
  });

  it("rejects a production runtime without R2 before reading secrets", () => {
    expect(() =>
      parseRuntimeConfig(
        productionBindings({
          SKILL_BUNDLES: undefined,
        }),
      ),
    ).toThrowError(
      expect.objectContaining({
        code: "PRODUCTION_BINDING_MISSING",
        fields: ["SKILL_BUNDLES"],
      }),
    );
  });

  it("rejects direct production database URLs", () => {
    expect(() =>
      parseRuntimeConfig(
        productionBindings({
          DATABASE_URL: "REDACTED",
        }),
      ),
    ).toThrowError(
      expect.objectContaining({
        code: "CONFIG_INVALID",
        fields: ["DATABASE_URL"],
      }),
    );
  });

  it("redacts unexpected errors into a stable diagnostic", () => {
    expect(safeConfigDiagnostic(new Error("contains-sensitive-detail"))).toEqual({
      code: "CONFIG_UNKNOWN",
      fields: [],
    });
    expect(
      safeConfigDiagnostic(
        new ConfigError("CONFIG_INVALID", "private detail", ["RUNTIME_ENV"]),
      ),
    ).toEqual({
      code: "CONFIG_INVALID",
      fields: ["RUNTIME_ENV"],
    });
  });
});
