  if (bindings.EMAIL_PROVIDER !== "cloudflare-email") {
    throw new ConfigError(
      environment === "local" ? "CONFIG_INVALID" : "PRODUCTION_ADAPTER_INVALID",
      "OTP authentication requires the Cloudflare Email Service provider",
