  if (authMode === "disabled") {
    return { auth: null, email: null };
  }
  validateCloudflareEmailProvider(bindings, environment);
  const missing: string[] = [];
  if (!isEmailServiceBinding(bindings.SEND_EMAIL)) {
    missing.push("SEND_EMAIL");
  }

