  ) {
    throw new Error("The development database contains an invalid bundle reference");
  }
}

async function verifyObject(path, reference, label) {
  const bytes = await readFile(path);
  if (
    bytes.byteLength !== reference.byteSize ||
    `sha256:${sha256(bytes)}` !== reference.digest
  ) {
    throw new Error(`${label} bundle does not match the development database`);
  }
  return bytes.byteLength;
}

export async function reconcileDevelopmentBundles(options = {}) {
  requireEnvironment("SKILLPLANE_DEV_CLOUDFLARE_API_TOKEN", {
    minimumLength: 20,
    trim: false,
  });
  const references =
    options.references ?? (await referencedBundles(developmentDatabase()));
  const getObject = options.getObject ?? wranglerObjectGet;
  const putObject = options.putObject ?? wranglerObjectPut;
  const sourceEnvironment = options.sourceEnvironment ?? sourceCloudflareEnvironment();
  const targetEnvironment =
    options.targetEnvironment ?? developmentCloudflareEnvironment();
  const directory = await mkdtemp(join(tmpdir(), "skillplane-dev-r2-"));
  let copied = 0;
  let existing = 0;
  let verifiedBytes = 0;
  try {
    for (const [index, reference] of references.entries()) {
      validateReference(reference);
      const sourcePath = join(directory, `${index}-source.zip`);
      const targetPath = join(directory, `${index}-target.zip`);
      const targetExists = await getObject(
        developmentBucket,
        reference.key,
        targetPath,
        targetEnvironment,
      );
      if (targetExists) {
        verifiedBytes += await verifyObject(
          targetPath,
          reference,
          "Existing development",
        );
        existing += 1;
        await unlink(targetPath);
        continue;
      }
      await unlink(targetPath).catch((error) => {
        if (error?.code !== "ENOENT") throw error;
      });
      const sourceExists = await getObject(
        productionBucket,
        reference.key,
        sourcePath,
        sourceEnvironment,
      );
      if (!sourceExists) {
        throw new Error("A database-referenced production bundle is missing");
      }
      await verifyObject(sourcePath, reference, "Production");
      const sourceBytes = await readFile(sourcePath);
      await putObject(developmentBucket, reference.key, sourceBytes, targetEnvironment);
      const uploaded = await getObject(
        developmentBucket,
        reference.key,
        targetPath,
        targetEnvironment,
      );
      if (!uploaded) {
        throw new Error("A copied development bundle could not be read back");
      }
      verifiedBytes += await verifyObject(targetPath, reference, "Copied development");
      copied += 1;
      await Promise.all([unlink(sourcePath), unlink(targetPath)]);
    }
  } finally {
    await rm(directory, { recursive: true, force: true });
  }
  return {
    ok: true,
    sourceBucket: productionBucket,
    targetBucket: developmentBucket,
    referenced: references.length,
    copied,
    existing,
    verifiedBytes,
  };
}

if (isMain(import.meta.url)) {
  process.stdout.write(
    `${JSON.stringify(await reconcileDevelopmentBundles(), null, 2)}\n`,
  );
}

