      snapshot: snapshot.rows[0]?.snapshot,
      inventory: {
        ssl: tls,
        migrations,
        bundleReferences,
        bundleReferenceDigest: sha256(
          Buffer.from(JSON.stringify(bundleReferences), "utf8"),
        ),
        postgres: {
          serverVersion: server.rows[0]?.version ?? "unknown",
          serverMajor,
          clientImage: `postgres:${serverMajor}-alpine`,
