    ],
    {
      cwd: repoRoot,
      encoding: "utf8",
      stdio: "inherit",
    },
  );
  process.exit(result.status ?? 1);
}

const result = spawnSync("pnpm", ["exec", "turbo", "run", "test:unit", ...args], {
  cwd: repoRoot,
  encoding: "utf8",
