const targets = [
  ['prod','https://app.skillplane.dev/api/v1/health/ready'],
  ['dev','https://app-dev.skillplane.dev/api/v1/health/ready'],
];
const rows=[];
for (let round=0; round<12; round++) {
  for (const [env,url] of targets) {
    const started=performance.now();
    try {
      const res=await fetch(`${url}?probe=${Date.now()}-${round}`, {headers:{'cache-control':'no-cache'}});
      const body=await res.json();
      rows.push({env,round,status:res.status,totalMs:Math.round(performance.now()-started),appTiming:res.headers.get('server-timing'),colo:(res.headers.get('cf-ray')||'').split('-').at(-1),postgresMs:body?.data?.checks?.postgres?.latencyMs,r2Ms:body?.data?.checks?.objectStorage?.latencyMs,requestId:body?.meta?.requestId});
    } catch (e) { rows.push({env,round,error:String(e)}); }
  }
}
for (const row of rows) console.log(JSON.stringify(row));
for (const env of ['prod','dev']) {
  const xs=rows.filter(r=>r.env===env && !r.error);
  const stats={env,count:xs.length,colo:[...new Set(xs.map(x=>x.colo))],status:[...new Set(xs.map(x=>x.status))]};
  for (const key of ['totalMs','postgresMs','r2Ms']) {
    const vs=xs.map(x=>x[key]).filter(Number.isFinite).sort((a,b)=>a-b);
    stats[key]={min:vs[0],median:vs[Math.floor(vs.length/2)],p95:vs[Math.min(vs.length-1,Math.floor(vs.length*.95))],max:vs.at(-1),avg:Math.round(vs.reduce((a,b)=>a+b,0)/vs.length)};
  }
  console.log('SUMMARY '+JSON.stringify(stats));
}
